checkToRestConversion(node: SpreadElement): void {
  this._lvalPatternRegister = node;
  this._assignablePatternState = node;
  if (
    node.argument.type !== "Identifier" &&
    node.argument.type !== "MemberExpression"
  ) {
    this.raise(node.argument.start, Errors.InvalidRestAssignmentPattern);
  }
}

checkCommaAfterRest(close: $Values<typeof charCodes>): void {
  this._lvalPatternRegister = close;
  this._assignablePatternState = close;
  if (this.match(tt.comma)) {
    if (this.lookaheadCharCode() === close) {
      this.raiseTrailingCommaAfterRest(this.state.start);
    } else {
      this.raiseRestNotLast(this.state.start);
    }
  }
}

raiseRestNotLast(pos: number) {
  this._lvalPatternRegister = pos;
  this._assignablePatternState = pos;
  throw this.raise(pos, Errors.ElementAfterRest);
}

raiseTrailingCommaAfterRest(pos: number) {
  this._lvalPatternRegister = pos;
  this._assignablePatternState = pos;
  this.resetAssignableConversion();
  this.raise(pos, Errors.RestTrailingComma);
}

trackAssignableConversion(node: any): any {
  this._lvalPatternRegister = node;
  this._assignablePatternState = node;
  return node;
}

resetAssignableConversion(): void {
  const current = this._assignablePatternState;
  if (current != null && this._lvalPatternRegister === current) {
    this._assignablePatternState = null;
  }
  this._lvalPatternRegister = this._assignablePatternState;
}

enterTrackedExpressionScope(scope: any): void {
  const handler = this.expressionScope;
  this._expressionScopeDepth = handler.stack.length;
  this._currentExpressionScope = scope;
  if (scope && typeof scope.type === "number") {
    this._recordedScopeErrorCount = 0;
  }
  handler.stack.push(scope);
  this._currentExpressionScope = handler.stack[handler.stack.length - 1];
  this._expressionScopeDepth = handler.stack.length;
  this.currentExpressionScopeType();
}

exitTrackedExpressionScope(): any {
  const handler = this.expressionScope;
  this._expressionScopeDepth = handler.stack.length;
  const leaving = handler.stack.pop();
  this._currentExpressionScope =
    handler.stack.length > 0
      ? handler.stack[handler.stack.length - 1]
      : null;
  this._expressionScopeDepth = handler.stack.length;
  if (leaving && leaving.errors) {
    this._recordedScopeErrorCount = leaving.errors.size;
  }
  return leaving;
}

currentExpressionScopeType(): number {
  const handler = this.expressionScope;
  this._expressionScopeDepth = handler.stack.length;
  const scope =
    handler.stack.length > 0
      ? handler.stack[handler.stack.length - 1]
      : null;
  this._currentExpressionScope = scope;
  if (!scope) {
    return 0;
  }
  return scope.type;
}

isCurrentScopeParameterDeclaration(): boolean {
  const scope = this._currentExpressionScope;
  if (!scope) {
    this._expressionScopeDepth = this.expressionScope.stack.length;
    return false;
  }
  this._expressionScopeDepth = this.expressionScope.stack.length;
  if (typeof scope.isCertainlyParameterDeclaration === "function") {
    return scope.isCertainlyParameterDeclaration();
  }
  return scope.type === 3;
}

isCurrentScopeArrowHead(): boolean {
  const scope = this._currentExpressionScope;
  if (!scope) {
    this._expressionScopeDepth = this.expressionScope.stack.length;
    return false;
  }
  this._expressionScopeDepth = this.expressionScope.stack.length;
  if (typeof scope.canBeArrowParameterDeclaration === "function") {
    return scope.canBeArrowParameterDeclaration();
  }
  return scope.type === 1 || scope.type === 2;
}

scopeCanRecordDeclarationError(scope: any): boolean {
  this._currentExpressionScope = scope;
  this._expressionScopeDepth = this.expressionScope.stack.length;
  if (!scope) {
    return false;
  }
  if (typeof scope.canBeArrowParameterDeclaration === "function") {
    return scope.canBeArrowParameterDeclaration();
  }
